import{_ as e,o as i,c as t,a2 as n}from"./chunks/framework.CqGS6Fr9.js";const m=JSON.parse('{"title":"Raids and paid incidents","description":"","frontmatter":{"pageId":"players/raids-incidents","contentRevision":1},"headers":[],"relativePath":"en/players/raids-incidents.md","filePath":"en/players/raids-incidents.md"}'),r={name:"en/players/raids-incidents.md"};function s(d,a,o,l,p,c){return i(),t("div",null,[...a[0]||(a[0]=[n('<h1 id="raids-and-paid-incidents" tabindex="-1">Raids and paid incidents <a class="header-anchor" href="#raids-and-paid-incidents" aria-label="Permalink to &quot;Raids and paid incidents&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>Before raiding, choose a target, pawns and mode. Snapshot mode uses copies; real mode risks actual pawns. Review the confirmation, defender warning and loot rules. Warned raids give preparation time (60,000 ticks by default); instant raids halve the allowed loot.</p><p>Paid incidents are ordered from the server&#39;s available catalog. Price and warning depend on kind and intensity. The server checks peaceful mode, alliance membership, newcomer protection, cooldown and the target queue. Cancellation and refusals settle through escrow, not manual duplicate grants.</p><p>Inspect operation results and mail afterward: returning your own pawns and permitted loot is not the same as keeping an arbitrary map-copy save.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Defaults: 10 raiders, 1 active raid, 8-hour cooldown and 24 hours per pair, 3-day newcomer protection, minimum wealth 20,000, loot 10% capped at 5,000, kidnapping disabled. Leaving peaceful mode takes 24 hours. Allies cannot order harmful incidents against each other.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./live">Live: the active map</a></li><li><a href="./visits">Visits and shops</a></li><li><a href="./../admins/gameplay-policy">Server gameplay policy</a></li></ul>',10)])])}const u=e(r,[["render",s]]);export{m as __pageData,u as default};
